const body = $json.body || {};
try {
  const entries = body.entry || [];
  for (const entry of entries) {
    const changes = entry.changes || [];
    for (const change of changes) {
      if (change.field === 'comments') {
        const val = change.value || {};
        const myId = '17841425833721941';

        // Prevent replying to own account comments
        if (val.from && String(val.from.id) !== String(myId) && val.text) {
          return [{
            json: {
              comment_id: val.id,
              comment_text: val.text,
              from_username: val.from.username || 'user',
              from_id: val.from.id,
              media_id: val.media ? val.media.id : null
            }
          }];
        }
      }
    }
  }
} catch (e) {
  console.error('Parse error:', e);
}
return [];

