const rawReply = $json.candidates?.[0]?.content?.parts?.[0]?.text;
const fallback = 'Thanks for tuning in! Appreciate your support 🚀';
const reply = (rawReply || fallback).trim().replace(/^"|"$/g, '');

let item = {};
try {
  item = $('Parse Reel Comment').item.json;
} catch (e) {
  item = $('Parse Reel Comment').first().json;
}

return {
  comment_id: item.comment_id,
  comment_text: item.comment_text,
  from_username: item.from_username,
  from_id: item.from_id,
  media_id: item.media_id,
  reply_text: reply
};
